import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"36、【明夷】 離下坤上","description":"周易尚氏學 - 36、【明夷】 離下坤上","frontmatter":{"title":"36、【明夷】 離下坤上","description":"周易尚氏學 - 36、【明夷】 離下坤上"},"headers":[],"relativePath":"classics/shangshi/041.md","filePath":"classics/shangshi/041.md"}'),s={name:"classics/shangshi/041.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_36、【明夷】-離下坤上" tabindex="-1">36、【明夷】 離下坤上 <a class="header-anchor" href="#_36、【明夷】-離下坤上" aria-label="Permalink to “36、【明夷】 離下坤上”">​</a></h1><p>鄭雲。夷傷也。日出地上。其明乃光。至其人地。明則傷矣。按二至四互坎。故曰艱。坤安故曰貞。利艱貞者。言當明夷之世。宜以艱苦貞定自守也。</p><p>彖曰。明入地中。明夷。內文明而外柔順。以蒙大難。文王以之。利艱貞。晦其明也。內難而能正其志。箕子以之。</p><p>離文明。坤柔順。離內坤外。故曰內文明而外柔順。坎為難。故曰以蒙大難。坤為文。震為王。故曰文王。文王國羌裡。幾經艱難。而後出之。故日以蒙大難。坤為黑。坎為隱伏。明伏地下。故曰晦其明。坎在下。故曰內難。坎為志為正。故曰內難而能正其志。震為子為箕。故曰箕子。易林賁之屯雲。章甫薦履。箕子佯狂。以屯震為箕子也。箕子紂請父。故曰內難。紂囚箕子。箕子佯狂為奴。晦明不用。僅以身免。故曰箕子以之。以用也。易凡於人名地名。無不從象生。除焦延壽外。無知此者。震箕象形。易林屢用。</p><p>象曰。明入地中。明夷。君子以蒞眾。用晦而明。</p><p>坤為眾。震為君子。蒞眾謂三也。用晦而明。言君子處明夷之世。仍自昭明德也。</p><p>初九。明夷于飛。垂其翼。君子於行。三日不食。有攸往。主人有言。</p><p>此與師六五義同也。辭在五而象全在應。初應在四。四體震。震為飛為翼。坤為下。故曰垂其翼。震為君子。為行。數三。離日故曰三日。震為口為食。坤閉。故三日不食。震為往。為主人。為言。故曰有攸往主人有言。蓋初雖應四。而為三所阻格。故飛則不能高。行則不得食。凡有所往。而為主人所惡。責讓不安。左傳僖十五年。晉筮遇歸妹之睽曰。西鄰責言。以歸妹上震為責言也。震言外向。與我相背。故曰賁言。茲曰有言。與責言義同也。易林同人之坎雲。喜其羽翼。飛上喬木。以坎中爻震為鼓為飛。為羽翼。又易林蒙之艮雲。。攫飯把肉。以就口食。以艮中爻震為口為食也。易頤象曰。自求口實。以頤下震為口食也。乃震飛震翼震口之象皆失傳。舊解皆以屬之離。離在地下。且為初爻。胡能飛哉。若食象益茫然不知所指。</p><h3 id="象曰。君子於行。義不食也。" tabindex="-1">象曰。君子於行。義不食也。 <a class="header-anchor" href="#象曰。君子於行。義不食也。" aria-label="Permalink to “象曰。君子於行。義不食也。”">​</a></h3><p>初潛龍勿用。況當明夷之世。方自晦之不暇。當然不得祿食也。</p><p>六二。明夷於左股。用拯馬壯吉。</p><p>釋文雲。股。馬王肅作般。孫堂雲。般盤之省。漢碑盤字常作股。股常作般。然則馬王雖作般。義仍作股。漢時般股通用不分也。互震為左。巽為股。巽伏不見。故曰夷於左股。三震為馬。拯。鄭雲承也。子夏傳作升。仍音承。用拯馬壯吉者。言二承三。三陽。故壯吉也。舊解獨惠棟謂馬謂三。而謂三升二故壯。則又非。承者順。謂陰順陽。象釋曰順。即釋拯義也。</p><h3 id="象曰。六二之吉。順以則也。" tabindex="-1">象曰。六二之吉。順以則也。 <a class="header-anchor" href="#象曰。六二之吉。順以則也。" aria-label="Permalink to “象曰。六二之吉。順以則也。”">​</a></h3><p>則者法也。陰以陽為則。順以則。謂陰順陽。釋拯馬之義也。乃舊解皆不知其所謂。故愈說愈晦。豈知象以解經。順即謂拯也。</p><p>九三。明夷於南。句狩。句得其大首。不可疾貞。</p><p>三遇坤。坤為夜為黑。震為南。左傳成十六年。晉筮遇復曰。南國戚（左足）。 以坤為國。震為南也。三南遇坤。故曰明夷於南。震為狩為大。坎為首為獲。故曰得其大首。言得其渠率也。詩大雅吳天疾威。傳。疾猶急也。不可疾。言雖得其大首。不可持之過急也。貞謂宜安定也。疾與貞相對為義。舊讀疾貞連文。九家謂不可疾正。最為害理。獨項氏玩辭。以貞自為句。與經義合。又舊讀以南狩連文。義亦不協。</p><h3 id="象曰。南狩之志。乃大得也。" tabindex="-1">象曰。南狩之志。乃大得也。 <a class="header-anchor" href="#象曰。南狩之志。乃大得也。" aria-label="Permalink to “象曰。南狩之志。乃大得也。”">​</a></h3><p>陽遇陰故大有得。</p><p>六四。入於左腹。獲明夷之心。於出門庭。</p><p>震為左。坤為腹。為門庭。為心。四坤體。故曰人於左腹。坤閣故曰獲明珍之心於出門庭。震為出。言行至四人坤。悉明夷之故。正在於是也。四當位有應。故無吉凶。坤心之象。益九五雲。有孚惠心。心調二。二坤體也。又益九五象雲。大得志。志亦謂坤。故易林需之否雲。志如死灰。以坤為死為志。人第知坎為心志。不知坤亦為心志。故易辭多誤解。</p><h3 id="象曰。入於左腹。獲心意也。" tabindex="-1">象曰。入於左腹。獲心意也。 <a class="header-anchor" href="#象曰。入於左腹。獲心意也。" aria-label="Permalink to “象曰。入於左腹。獲心意也。”">​</a></h3><p>坤為心意。故曰獲心意。舊解多以三升五成坎為心意。穿鑿無理。不可從。</p><p>六五。箕子之明夷。利貞。</p><p>震為箕子已見前。據易林。此箕子則孩子也。夬之中孚雲。道路不通。孩子心饋。以中孚互震為孩子。又家人之龔雲。孩子貪餌。以伏震為孩子。又損之大畜雲。嬰兒孩子。未有知識。以大畜上艮為嬰兒。互震為孩子。凡易林取象。無不本之易。易他處無孩子象也。宋吳械韻補雲。古亥字音喜亦音其。按亥字既讀為其。則其字亦必讀為亥。淮南子時則訓。a （？）萁隧火。高誘注。萁讀為該備之該。即a（？） 該燧火也。真既讀為該。於是亥孩刻亥（上草）。與其箕常通用。書微子。我舊雲刻子。論衡作我舊雲孩子。孩子謂紂。言久知其愚蒙昏饋（左　）也。是應為孩子。而作刻子。墨子非攻篇。紂播棄黎老。賊誅孩子。是孩子即箕子。古之所謂誅。不盡是殺。賊誅孩子。即幽囚箕子也。是應為箕子。而作孩子。故此處六五之箕子。漢趙賓又作亥（上草）茲。夫墨子以孩子作箕子。則明夷六五之箕子。易林作孩子。正與墨子合。與論衡同。孩子皆謂紂也。孩箕刻亥（上草）。皆非訛字。以音同古通用。猶盤桓之盤。或作盤。作盤（下木）。作般。皆非訛字也。易林雲。嬰兒孩子。未有知識。釋孩子之義也。六五天子位。孩子之明夷。謂紂昏蒙。惟其指紂。故象傳推及於文王箕子。不然。象傳之箕子。胡以無一異讀哉。故易林姤之明夷雲。西戎為疾。幽君去室。明夷六五君位。坤黑。故曰幽君。坎為室。六五在坎外。故曰幽君去室。幽君即釋孩子之義。又困之明夷。邃態作雲。蒙覆大臣。坤為雲。亦釋昏蒙之義。又京房易傳明夷雲。君暗臣明。不可止。君暗謂六五。臣明謂六二。亦以五為君。不以為紂臣。又象傳曰。孩子之貞。明不可息也。貞正也。言孩子居天子之正位。天子一日萬幾。故明不可息。若箕子已晦其明矣。有何不可息。古今釋者千百家。於此語未有能通者。蓋文王與微子。不欲明斥紂。故以孩子為代名。猶麥秀歌之謂狡童也。觀墨子以箕子為孩子。則此之箕子。亦為孩子。易林之讀。獨得其真。自孩箕音同通用之義弗明。竟作紂臣矣。豈知孩子即謂紂。與微子之孩子同。彼夫趙賓作亥（上草）茲。劉向荀爽作亥（上草）滋。蜀才作其子。王弼作其茲。惠棟作亥子。雖與象傳義不合。然皆知作紂臣之必非。乃孔疏不從王注。而從馬融。竟作紂臣解。疏已。五本君位。馬融作紂臣解。亦知其不安。而以箕子演疇。有君德為解。益可證易林以孩子為紂之精。五承乘皆陰。下又無應。故曰利貞。謂宜艱貞自守不妄動也。</p><h3 id="象曰。箕子之貞。明不可息也。" tabindex="-1">象曰。箕子之貞。明不可息也。 <a class="header-anchor" href="#象曰。箕子之貞。明不可息也。" aria-label="Permalink to “象曰。箕子之貞。明不可息也。”">​</a></h3><p>五為天子。天子一日萬幾。明息則政亂矣。故曰明不可息。</p><p>上六。不明晦。初登於天。後入於地。</p><p>明夷之初為晉。晉日在地上而為晝。故曰初登於天。乃晉覆成明夷。日在地下而為夜。故曰後人於地。人地故晦而不明。卦正如彼。覆則如此。此文王示序卦之義也。</p><h3 id="象曰。初登於天。照四國也。後入於地。失則也。" tabindex="-1">象曰。初登於天。照四國也。後入於地。失則也。 <a class="header-anchor" href="#象曰。初登於天。照四國也。後入於地。失則也。" aria-label="Permalink to “象曰。初登於天。照四國也。後入於地。失則也。”">​</a></h3><p>坤為國。震卦數四。故曰四國。則謂三。上為四五所格。不能應三。故曰失則。此則字與六二順以則。謙六四不違則義同。皆謂陽。舊解皆不知失則之故何在。泛說之。非。</p>',30)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
